// Headless demo shim for `@xulo/ui`. Without a browser or test harness these
// components are just virtual nodes: Screen/VStack/HStack/Button/Text/Input
// funnel their props through an element factory so a program can be exercised
// end-to-end. A default `__xulo_mount` pretty-prints the element tree (the
// generated bundle calls `__xulo_mount(main())` when one is defined).

const el = (kind) => (props) => ({ kind, ...(props || {}) });

export const Screen = el("Screen");
export const VStack = el("VStack");
export const HStack = el("HStack");
export const Button = el("Button");
export const Input = el("Input");
export const Text = el("Text");

if (typeof globalThis.__xulo_mount !== "function") {
  // Components compile to a wrapper exposing the element as a lazy getter;
  // resolve wrappers so the tree prints as elements. Elements themselves may
  // carry a `value` prop (e.g. Input), so only unwrap objects without a `kind`.
  const resolve = (n) =>
    n && typeof n === "object" && n.kind === undefined && n.value !== undefined
      ? n.value
      : n;
  const render = (node, depth) => {
    node = resolve(node);
    if (!node || typeof node !== "object") return [];
    const pad = "  ".repeat(depth);
    const lines = [`${pad}<${node.kind}>`];
    for (const [key, value] of Object.entries(node)) {
      if (key === "kind" || key === "children") continue;
      if (typeof value === "string" || typeof value === "number") {
        lines.push(`${pad}  ${key}: ${value}`);
      }
    }
    for (const child of node.children || []) {
      lines.push(...render(child, depth + 1));
    }
    lines.push(`${pad}</${node.kind}>`);
    return lines;
  };
  globalThis.__xulo_mount = (root) => console.log(render(root, 0).join("\n"));
}